  Optional<Address> authorizer();

  /**
   * Return the nonce
   *
   * @return the nonce
   */
  long nonce();

  /**
   * Return the recovery id.
   *
   * @return byte
   */
  byte v();

  /**
   * Return the r value of the signature.
   *
   * @return r value
   */
  BigInteger r();

  /**
   * Return the s value of the signature.
   *
   * @return s value
   */
  BigInteger s();
}
